// MapLibre style: flat illustrated-map look (peach land, muted teal water with
// small wave marks, soft green parks, cream roads), on OpenFreeMap vector
// tiles (OpenMapTiles schema, no API key). Label glyphs are self-hosted SDFs
// generated by scripts/make-glyphs.mjs (Inter; Cormorant for monument names).

export const PAL = {
  land: '#f3d5b3', landLight: '#f8e6cf', landEdge: '#e2b991',
  water: '#8dbfbd', waterDeep: '#79b0ae', waterLine: '#6fa5a3', wave: '#c4e0dc',
  park: '#b5d39a', parkDeep: '#98c283', sand: '#f6dfbf',
  road: '#fdf3e4', roadCase: '#e7c4a0',
  bOff: '#f7ecdd', bWarm: '#efd2b4', bTerra: '#e0a585', bTerraDeep: '#d38f6e', bLine: '#c99877',
  text: '#3e4f4f', textSoft: '#6d7b78', teal: '#2f7a76', tealDeep: '#245f5c', gold: '#d9a93f',
};

const SERIF = ['Cormorant SemiBold'];
const SANS = ['Inter Medium'];
const SANS_B = ['Inter SemiBold'];
// Latin-only: our generated glyphs cover Latin ranges (Turkish included).
const NAME = ['coalesce', ['get', 'name:tr'], ['get', 'name:latin']];
const z = (...stops) => ['interpolate', ['exponential', 1.6], ['zoom'], ...stops];

export function buildStyle({ hiddenNames = [] } = {}) {
  const base = new URL('.', document.baseURI).href;
  const majorRoads = ['in', ['get', 'class'], ['literal', ['motorway', 'trunk', 'primary', 'secondary', 'tertiary']]];
  const minorRoads = ['in', ['get', 'class'], ['literal', ['minor', 'service', 'track', 'raceway']]];
  return {
    version: 8,
    name: 'Illustrated',
    glyphs: base + 'fonts/{fontstack}/{range}.pbf',
    sources: {
      omt: { type: 'vector', url: 'https://tiles.openfreemap.org/planet',
        attribution: '<a href="https://openfreemap.org" target="_blank">OpenFreeMap</a> © <a href="https://www.openmaptiles.org/" target="_blank">OpenMapTiles</a> Veri © <a href="https://www.openstreetmap.org/copyright" target="_blank">OpenStreetMap</a>' },
    },
    sky: {
      'sky-color': '#cfe6e4', 'horizon-color': '#f8e6cf', 'fog-color': PAL.land,
      'sky-horizon-blend': 0.6, 'horizon-fog-blend': 0.5, 'fog-ground-blend': 0.85, 'atmosphere-blend': 0,
    },
    layers: [
      { id: 'land', type: 'background', paint: { 'background-color': PAL.land } },

      { id: 'landcover', type: 'fill', source: 'omt', 'source-layer': 'landcover',
        filter: ['in', ['get', 'class'], ['literal', ['grass', 'wood', 'farmland', 'wetland']]],
        paint: { 'fill-color': PAL.park, 'fill-opacity': 0.75 } },
      { id: 'landcover-sand', type: 'fill', source: 'omt', 'source-layer': 'landcover',
        filter: ['==', ['get', 'class'], 'sand'], paint: { 'fill-color': PAL.sand } },
      { id: 'landuse-green', type: 'fill', source: 'omt', 'source-layer': 'landuse',
        filter: ['in', ['get', 'class'], ['literal', ['cemetery', 'grass', 'park', 'garden']]],
        paint: { 'fill-color': PAL.park, 'fill-opacity': 0.85 } },
      { id: 'park', type: 'fill', source: 'omt', 'source-layer': 'park',
        paint: { 'fill-color': PAL.park, 'fill-opacity': 0.85, 'fill-outline-color': PAL.parkDeep } },

      // Water: muted teal with a thin soft shoreline and small wave marks
      { id: 'water', type: 'fill', source: 'omt', 'source-layer': 'water',
        filter: ['!=', ['get', 'brunnel'], 'tunnel'], paint: { 'fill-color': PAL.water } },
      { id: 'water-waves', type: 'fill', source: 'omt', 'source-layer': 'water', minzoom: 13,
        filter: ['!=', ['get', 'brunnel'], 'tunnel'], paint: { 'fill-pattern': 'waves' } },
      { id: 'water-shore', type: 'line', source: 'omt', 'source-layer': 'water',
        paint: { 'line-color': PAL.waterLine, 'line-width': z(12, 0.8, 18, 2.4), 'line-opacity': 0.6 } },
      { id: 'waterway', type: 'line', source: 'omt', 'source-layer': 'waterway',
        paint: { 'line-color': PAL.water, 'line-width': z(12, 0.8, 18, 3) } },

      // Roads: cream bands with a thin warm casing (drawn under buildings)
      { id: 'path', type: 'line', source: 'omt', 'source-layer': 'transportation', minzoom: 15,
        filter: ['in', ['get', 'class'], ['literal', ['path', 'pedestrian']]],
        layout: { 'line-cap': 'round', 'line-join': 'round' },
        paint: { 'line-color': PAL.road, 'line-opacity': 0.85, 'line-width': z(15, 1, 18, 4) } },
      { id: 'road-minor-case', type: 'line', source: 'omt', 'source-layer': 'transportation', filter: minorRoads, minzoom: 15,
        layout: { 'line-cap': 'round', 'line-join': 'round' },
        paint: { 'line-color': PAL.roadCase, 'line-width': z(15, 2.4, 18, 9) } },
      { id: 'road-minor', type: 'line', source: 'omt', 'source-layer': 'transportation', filter: minorRoads,
        layout: { 'line-cap': 'round', 'line-join': 'round' },
        paint: { 'line-color': PAL.road, 'line-width': z(13, 0.6, 15, 1.4, 18, 7) } },
      { id: 'road-major-case', type: 'line', source: 'omt', 'source-layer': 'transportation', filter: majorRoads,
        layout: { 'line-cap': 'round', 'line-join': 'round' },
        paint: { 'line-color': PAL.roadCase, 'line-width': z(12, 1.5, 15, 5, 18, 17) } },
      { id: 'road-major', type: 'line', source: 'omt', 'source-layer': 'transportation', filter: majorRoads,
        layout: { 'line-cap': 'round', 'line-join': 'round' },
        paint: { 'line-color': PAL.road, 'line-width': z(12, 1, 15, 3.6, 18, 14) } },
      { id: 'rail', type: 'line', source: 'omt', 'source-layer': 'transportation',
        filter: ['in', ['get', 'class'], ['literal', ['rail', 'transit']]],
        paint: { 'line-color': PAL.bLine, 'line-opacity': 0.6, 'line-width': z(13, 0.6, 18, 1.6), 'line-dasharray': [3, 2] } },

      // Flat off-white / terracotta footprints with a thin same-hue outline — not extruded
      { id: 'building', type: 'fill', source: 'omt', 'source-layer': 'building', minzoom: 13,
        paint: {
          'fill-color': ['step', ['to-number', ['get', 'render_height'], 0],
            PAL.bWarm, 6, PAL.bOff, 10, PAL.bTerra, 16, PAL.bWarm, 24, PAL.bOff, 40, PAL.bTerraDeep],
          'fill-opacity': ['interpolate', ['linear'], ['zoom'], 13, 0.45, 15, 1],
        } },
      { id: 'building-line', type: 'line', source: 'omt', 'source-layer': 'building', minzoom: 15,
        paint: { 'line-color': PAL.bLine, 'line-opacity': 0.75, 'line-width': z(15, 0.4, 18, 1) } },

      // Labels
      ...['point', 'line'].map(placement => ({
        id: 'water-name-' + placement, type: 'symbol', source: 'omt', 'source-layer': 'water_name',
        filter: ['==', ['geometry-type'], placement === 'line' ? 'LineString' : 'Point'],
        layout: { 'text-field': NAME, 'text-font': SANS_B, 'text-size': 17, 'text-letter-spacing': 0.08, 'symbol-placement': placement },
        paint: { 'text-color': '#ffffff', 'text-halo-color': PAL.waterLine, 'text-halo-width': 0.8 } })),
      { id: 'street-name', type: 'symbol', source: 'omt', 'source-layer': 'transportation_name', minzoom: 15,
        layout: { 'text-field': NAME, 'text-font': SANS, 'symbol-placement': 'line', 'text-max-angle': 30,
          'text-size': ['interpolate', ['linear'], ['zoom'], 15, 10.5, 18, 13] },
        paint: { 'text-color': PAL.textSoft, 'text-halo-color': PAL.road, 'text-halo-width': 1.4 } },
      { id: 'poi', type: 'symbol', source: 'omt', 'source-layer': 'poi', minzoom: 16,
        filter: ['all',
          ['in', ['get', 'class'], ['literal', ['place_of_worship', 'attraction', 'monument', 'museum', 'park', 'castle', 'fountain', 'historic']]],
          ['!', ['in', ['get', 'name'], ['literal', hiddenNames]]]],
        layout: { 'text-field': NAME, 'text-font': SERIF, 'text-size': 15, 'text-max-width': 8, 'text-padding': 6 },
        paint: { 'text-color': PAL.tealDeep, 'text-halo-color': PAL.landLight, 'text-halo-width': 1.6 } },
      { id: 'place-small', type: 'symbol', source: 'omt', 'source-layer': 'place',
        filter: ['in', ['get', 'class'], ['literal', ['suburb', 'quarter', 'neighbourhood']]],
        layout: { 'text-field': ['upcase', NAME], 'text-font': SANS_B, 'text-letter-spacing': 0.16, 'text-max-width': 9,
          'text-size': ['interpolate', ['linear'], ['zoom'], 13, 10.5, 17, 13] },
        paint: { 'text-color': PAL.text, 'text-opacity': 0.75, 'text-halo-color': PAL.landLight, 'text-halo-width': 1.6 } },
      { id: 'place-city', type: 'symbol', source: 'omt', 'source-layer': 'place', maxzoom: 14,
        filter: ['in', ['get', 'class'], ['literal', ['city', 'town']]],
        layout: { 'text-field': NAME, 'text-font': SANS_B, 'text-size': 18, 'text-letter-spacing': 0.06 },
        paint: { 'text-color': PAL.text, 'text-halo-color': PAL.landLight, 'text-halo-width': 2 } },
    ],
  };
}

// --- Pattern image (generated, so the bundle carries no image assets) ---

/** Sparse, small double-wave marks on a transparent tile, drawn at 2x. */
export function wavesImage() {
  const S = 2, W = 96 * S, H = 64 * S;
  const c = document.createElement('canvas'); c.width = W; c.height = H;
  const x = c.getContext('2d');
  x.strokeStyle = PAL.wave; x.lineWidth = 1.6 * S; x.lineCap = 'round'; x.lineJoin = 'round';
  const mark = (cx, cy) => {               // "︶︶" — two small humps
    x.beginPath();
    for (let k = 0; k < 2; k++) { const ox = cx + k * 7 * S; x.moveTo(ox - 3.5 * S, cy); x.quadraticCurveTo(ox, cy - 4 * S, ox + 3.5 * S, cy); }
    x.stroke();
  };
  mark(18 * S, 18 * S);
  mark(66 * S, 48 * S);
  return { data: x.getImageData(0, 0, W, H), pixelRatio: S };
}
